effect.shader:
void main() {
    vec4 color = texture(inputImg, acScreenNorm);

    // A correção por acAspect é o que impede a vinheta de virar uma elipse
    // achatada num projeto 16:9. Sem ela, o círculo só fica redondo em
    // composição quadrada.
    vec2 offset = (acScreenNorm - center) * vec2(acAspect, 1.0) * 2.0;
    float dist = length(offset);

    float mask = 1.0 - smoothstep(radius, radius + softness, dist);
    float factor = mix(1.0, mask, amount);

    // Mistura em direção à cor escolhida, não multiplica. Assim dá para fazer
    // vinheta branca, azulada ou o que for — não só preta.
    fragColor = vec4(mix(tint.rgb, color.rgb, factor), color.a);
}
